def _table_create(name: str, schema: dict[str, Any], raw: dict[str, Any]) -> dict[str, Any]:
    keys = [(k, "HASH" if i == 0 else "RANGE") for i, k in enumerate(schema["keys"])]
    attrs = dict(schema["keys"])
    gsis = []
    for g in raw.get("gsis") or []:
        gk = [(g["partition_key"]["name"], "HASH")] + ([(g["sort_key"]["name"], "RANGE")] if g.get("sort_key") else [])
        attrs[g["partition_key"]["name"]] = g["partition_key"].get("type", "S")
        if g.get("sort_key"):
            attrs[g["sort_key"]["name"]] = g["sort_key"].get("type", "S")
        gsis.append({"IndexName": g["index_name"], "KeySchema": [{"AttributeName": k, "KeyType": t} for k, t in gk],
                     "Projection": {"ProjectionType": "ALL"}})
    create = {"TableName": name, "BillingMode": "PAY_PER_REQUEST",
              "KeySchema": [{"AttributeName": k, "KeyType": t} for k, t in keys],
              "AttributeDefinitions": [{"AttributeName": a, "AttributeType": t} for a, t in attrs.items()]}
    if gsis:
        create["GlobalSecondaryIndexes"] = gsis
    return create


def _monolith_tables(facts: Facts, names: dict[str, str] | None = None) -> list[dict[str, Any]]:
    """The monolith's tables to create, under the names it actually uses."""
    out = []
    for t in (facts.report.get("dynamodb_info") or {}).get("table_schemas") or []:
        name = (t.get("table") or {}).get("default_name")
        if name in facts.tables:
            actual = (names or {}).get(name, name)
            out.append({"name": actual, "create": _table_create(actual, facts.tables[name], t)})
    return out


def _rename_tables(value: Any, names: dict[str, str]) -> Any:
    """Table names in fixtures / fault rules / records, through `names`
    (dict keys and "table" fields)."""
    if isinstance(value, list):
        return [_rename_tables(v, names) for v in value]
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            k2 = names.get(k, k)
            if k in ("table", "queue") and isinstance(v, str):
                out[k2] = names.get(v, v)
            elif k == "tables" and isinstance(v, list):
                out[k2] = [names.get(x, x) if isinstance(x, str) else x for x in v]
            else:
                out[k2] = _rename_tables(v, names)
        return out
    return value


def _aliases(case: dict[str, Any]) -> list[str]:
    """The aliases a case uses, in order of first use."""
    out: list[str] = []
    if case.get("identity"):
        out.append(case["identity"])
    for s in case.get("steps") or []:
        if s.get("identity"):
            out.append(s["identity"])
        for v in _vars_used({k: s.get(k) for k in ("path", "query", "headers", "body", "form", "raw_body")}):
            if "." in v:
                out.append(v.split(".", 1)[0])
    return list(dict.fromkeys(out))


def build_units(assets: dict[str, Any]) -> list[dict[str, Any]]:
    cases = sorted((c for c in assets["cases"] if "_load_error" not in c), key=lambda c: c["id"])
    by_id = {c["id"]: c for c in cases}

    def unit(c: dict[str, Any], uid: str, rules: list[dict[str, Any]]) -> dict[str, Any]:
        fixtures: dict[str, list[Any]] = {}
        for name in c.get("fixtures") or []:
            for table, items in assets["fixtures"][name].items():
                fixtures.setdefault(table, []).extend(items)
        return {"id": uid, "case": c["id"], "identity": c.get("identity"), "aliases": _aliases(c),
                "fixtures": fixtures, "steps": c["steps"], "rules": rules}

    units = [unit(c, c["id"], []) for c in cases]
    for f in sorted(assets["faults"], key=lambda f: f["id"]):
        units += [unit(by_id[cid], f"{f['id']}/{cid}", f["rules"]) for cid in f["cases"]]
    return units


def _observed(facts: Facts, r: dict[str, Any], symbols: dict[str, str] | None = None) -> dict[str, Any]:

const names = [];
  let rx = '';
  for (const part of resource.split(/(\{\w+\+?\}|:\w+)/)) {
    const m = /^\{(\w+)(\+?)\}$/.exec(part) || /^:(\w+)()$/.exec(part);
    if (m) { names.push(m[1]); rx += m[2] ? '(.+)' : '([^/]+)'; } else rx += part.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }
  const m = new RegExp('^' + rx + '$').exec(concrete);
  if (!m) return null;
  return Object.fromEntries(names.map((n, i) => [n, m[i + 1]]));
}

function claimValue(v, httpApi) {
  if (Array.isArray(v)) return httpApi ? '[' + v.map(String).join(' ') + ']' : v.map(String).join(',');
  return String(v);
}

function buildEvent(unit, step, route, alias, requestId) {
  const [rawPath, qs] = step.path.split(/\?(.*)/s);
  const multi = {};
  for (const [k, v] of new URLSearchParams(qs || '')) (multi[k] = multi[k] || []).push(v);
  for (const [k, v] of Object.entries(step.query || {})) (multi[k] = multi[k] || []).push(String(v));
  const headers = { ...(step.headers || {}) };
  const has = (h) => Object.keys(headers).some((k) => k.toLowerCase() === h);
  let body = null;
  if ('body' in step) {
    body = JSON.stringify(step.body);
    if (!has('content-type')) headers['Content-Type'] = 'application/json';
  } else if ('form' in step) {
    body = new URLSearchParams(Object.entries(step.form).map(([k, v]) => [k, String(v)])).toString();
    if (!has('content-type')) headers['Content-Type'] = 'application/x-www-form-urlencoded';
  } else if ('raw_body' in step) {
    body = step.raw_body;
  }
  if (body !== null && !has('content-length')) headers['Content-Length'] = String(Buffer.byteLength(body));
  const params = pathParams(route.resource, rawPath) || {};
  const method = step.method.toUpperCase();
  const rc = { resourcePath: route.resource, httpMethod: method, path: rawPath, stage: 'Prod', requestId,
               identity: { sourceIp: '127.0.0.1' }, accountId: '000000000000' };
  if (route.authorized && alias) {
    const c = unit.auth[alias].claims;
    const claims = { sub: c.sub, 'cognito:username': c['cognito:username'] || c.sub };
    for (const [k, v] of Object.entries(c)) if (k !== 'sub') claims[k] = claimValue(v, route.http_api);
    rc.authorizer = { claims };
  }
  const single = Object.fromEntries(Object.entries(multi).map(([k, v]) => [k, v[v.length - 1]]));
  return {
    ...(route.http_api ? { version: '1.0' } : {}),
    resource: route.resource, path: rawPath, httpMethod: method,
    headers: Object.keys(headers).length ? headers : null,
    multiValueHeaders: Object.keys(headers).length ? Object.fromEntries(Object.entries(headers).map(([k, v]) => [k, [v]])) : null,
    queryStringParameters: Object.keys(single).length ? single : null,
    multiValueQueryStringParameters: Object.keys(multi).length ? multi : null,
    pathParameters: Object.keys(params).length ? params : null, stageVariables: null, requestContext: rc,
    body, isBase64Encoded: false,
  };
}

// The identity a request authenticates as: the alias whose identity header it
// carries unchanged (a garbage or other token, or none, is no identity).
function authenticatedAs(unit, headers) {
  const h = lower(headers);
  for (const [alias, a] of Object.entries(unit.auth || {})) {
    const want = lower(a.header);
    if (Object.keys(want).length && Object.entries(want).every(([k, v]) => h[k] === v)) return alias;
  }
  return null;
}

