    """Admin membership is read from UserGroupsTable on every request; no row
    (or a failed read) means no groups, never a 401 (SI-10)."""
    try:
        response = user_groups_table.get_item(Key={"sub": sub})
    except Exception as exc:  # noqa: BLE001
        print(f"Error getting user groups {sub}: {str(exc)}")
        return False
    item = response.get("Item") or {}
    groups = item.get("groups") or []
    return "Admin" in list(groups)


def parse_body(event):
    """A body that is absent or not parseable reads as no data, like the
    monolith's `request.get_json()` on an empty request."""
    raw = event.get("body")
    if raw is None or raw == "":
        return None
    if isinstance(raw, dict):
        return raw
    try:
        return json.loads(raw)
    except ValueError:
        return None


def add_loyalty_points(customer_id, points):
    if not isinstance(points, (int, float)) or points <= 0:
        raise ValueError("Points must be a positive number")

    loyalty_entry = {
        "id": str(uuid.uuid4()),
        "customerId": customer_id,
        "points": int(points),
        "flag": "active",
        # No timezone suffix, same shape as the monolith's datetime.now().isoformat() (SI-15).
        "date": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
    }
    try:
        loyalty_table.put_item(Item=to_dynamodb(loyalty_entry))
    except Exception as exc:  # noqa: BLE001 - a failed write is a 400, never a 5xx
        raise ValueError(f"Failed to add loyalty points: {str(exc)}")

    return {
        "message": "Loyalty points added successfully",
        "customerId": customer_id,
        "pointsAdded": int(points),
    }


def lambda_handler(event, context):
    try:
        customer_id = (event.get("pathParameters") or {}).get("customer_id")

        if not is_admin(claims_of(event).get("sub")):
            return json_response(403, {"error": "Admin privileges required"})

        data = parse_body(event)
        if not data or "points" not in data:
            return json_response(400, {"error": "points is required"})

        return json_response(200, add_loyalty_points(customer_id, data["points"]))
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})

"""payments-collect: POST /payments/collect

No authentication (business_rules[0]). Only the simulation branch is
migrated - no stripe dependency, no STRIPE_SECRET_KEY (SI-7): the price is
always 150 and the receipt URL is the chargeId interpolated as the
monolith's f-string does, so a non-string scalar chargeId appears verbatim
