        return raw
    try:
        return json.loads(raw)
    except ValueError:
        return None


def collect_payment(charge_id):
    """The monolith's simulation branch, with the in-process record moved
    into PaymentTable (SI-6)."""
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    # The table's key must be a scalar. Check it here so an unhashable
    # chargeId raises the same TypeError the monolith raised on its
    # in-memory bookkeeping line, before anything is stored (SI-19).
    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    receipt_url = f"https://payment.example.com/receipts/{charge_id}"
    price = 150

    payment_table.put_item(Item=to_dynamodb({
        "chargeId": charge_id,
        "receiptUrl": receipt_url,
        "price": price,
        "status": "captured",
        "mode": "simulation",
    }))

    return {"receiptUrl": receipt_url, "price": price}


def lambda_handler(event, context):
    try:
        data = parse_body(event)
        if not data or "chargeId" not in data:
            return json_response(400, {"error": "chargeId is required"})

        return json_response(200, collect_payment(data["chargeId"]))
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})

"""payments-refund: POST /payments/refund

No authentication, no amount check, no check that the chargeId was ever
collected: the simulation refund always succeeds and hands back a freshly
generated refundId (SI-6, SI-7, business_rules[2]). If a payment record
for that chargeId exists its status becomes 'refunded' - a conditional
update, so a chargeId that was never collected leaves no row behind and
is not an error. Nothing here touches bookings (business_rules[4]).
Every response carries the app-wide headers (SI-14).
"""
import json
import os
import secrets

import boto3

PAYMENT_TABLE_NAME = os.environ["PAYMENT_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
payment_table = _dynamodb.Table(PAYMENT_TABLE_NAME)
CONDITIONAL_CHECK_FAILED = _dynamodb.meta.client.exceptions.ConditionalCheckFailedException


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def parse_body(event):
    """A body that is absent or not parseable reads as no data, like the
    monolith's `request.get_json()` on an empty request."""
    raw = event.get("body")
    if raw is None or raw == "":
        return None
    if isinstance(raw, dict):
        return raw
    try:
        return json.loads(raw)
    except ValueError:
        return None


def refund_payment(charge_id):
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    # Same guard as collect: an unhashable chargeId fails with the monolith's
    # TypeError before anything is written (SI-19).
    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    refund_id = secrets.token_urlsafe(16)

    try:
        payment_table.update_item(
            Key={"chargeId": charge_id},
            UpdateExpression="SET #status = :status",
            ExpressionAttributeNames={"#status": "status"},
            ExpressionAttributeValues={":status": "refunded"},
            ConditionExpression="attribute_exists(chargeId)",
        )
    except CONDITIONAL_CHECK_FAILED:
        # Never collected: nothing to mark, and no record is created.
        pass

    return {"refundId": refund_id}


def lambda_handler(event, context):
    try:
        data = parse_body(event)
        if not data or "chargeId" not in data:
