        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity - :dec",
            ConditionExpression="seatCapacity > :zero AND attribute_exists(id)",
            ExpressionAttributeValues={":dec": 1, ":zero": 0},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError(f"Flight {flight_id} is fully booked or does not exist")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to reserve seat: {str(exc)}")


def get_flight(flight_id):
    try:
        response = flight_table.get_item(Key={"id": flight_id})
    except Exception as exc:  # noqa: BLE001 - a failed read reads as missing
        print(f"Error getting flight {flight_id}: {str(exc)}")
        return None
    if "Item" in response:
        return from_dynamodb(response["Item"])
    return None


def release_flight_seat(flight_id):
    """The cap comes from the flight item's own maximumSeating."""
    try:
        flight = get_flight(flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")

        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity + :inc",
            ConditionExpression="seatCapacity < :max",
            ExpressionAttributeValues={":inc": 1, ":max": flight["maximumSeating"]},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError("Cannot release seat, already at maximum capacity")
    except Exception as exc:  # noqa: BLE001 - includes the "does not exist" above
        raise ValueError(f"Failed to release seat: {str(exc)}")


# --- booking steps -----------------------------------------------------------

def validate_booking_request(booking_data):
    required_fields = ["outboundFlightId", "customerId", "chargeId"]
    return all(field in booking_data for field in required_fields)


def create_booking(booking_data):
    booking_id = str(uuid.uuid4())
    booking = {
        "id": booking_id,
        "bookingOutboundFlightId": booking_data["outboundFlightId"],
        "checkedIn": False,
        "customer": booking_data["customerId"],
        "paymentToken": booking_data["chargeId"],
        "status": "UNCONFIRMED",
        "createdAt": now_iso(),
        "bookingReference": None,
    }
    try:
        booking_table.put_item(Item=to_dynamodb(booking))
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to create booking: {str(exc)}")
    return booking


def reserve_booking(booking_data):
    if not validate_booking_request(booking_data):
        raise ValueError("Invalid booking request: missing required fields")
    return create_booking(booking_data)["id"]


def update_booking_status(booking_id, status, booking_reference=None):
    update_expr = "SET #status = :status"
    expr_attr_names = {"#status": "status"}
    expr_attr_values = {":status": status}

    if booking_reference:
        update_expr += ", bookingReference = :ref"
        expr_attr_values[":ref"] = booking_reference

    try:
        booking_table.update_item(
            Key={"id": booking_id},
            UpdateExpression=update_expr,
            ExpressionAttributeNames=expr_attr_names,
            ExpressionAttributeValues=expr_attr_values,
            ConditionExpression="attribute_exists(id)",
            ReturnValues="ALL_NEW",
        )
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError(f"Booking {booking_id} not found")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to update booking: {str(exc)}")


def confirm_booking(booking_id):
    """One conditional write does both the existence check and the update
    (GAP-17 / D-16: no read-back that eventual consistency could lose)."""
    reference = secrets.token_urlsafe(4)
    update_booking_status(booking_id, "CONFIRMED", reference)
    return reference


def cancel_booking(booking_id):
    update_booking_status(booking_id, "CANCELLED")
    return True


# --- payment steps -----------------------------------------------------------

def collect_payment(charge_id):
    """Simulation branch only (SI-7), record kept in PaymentTable (SI-6)."""
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    # Same guard as payments-collect: the table key must be a scalar, and the
    # text has to be the monolith's TypeError so it escapes the except
    # ValueError of this step and lands in the catch-all rollback (SI-19).
    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    receipt_url = f"https://payment.example.com/receipts/{charge_id}"
    price = 150

    payment_table.put_item(Item=to_dynamodb({
        "chargeId": charge_id,
        "receiptUrl": receipt_url,
        "price": price,
        "status": "captured",
        "mode": "simulation",
    }))

    return {"receiptUrl": receipt_url, "price": price}


def refund_payment(charge_id):
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    refund_id = secrets.token_urlsafe(16)

    try:
        payment_table.update_item(
            Key={"chargeId": charge_id},
            UpdateExpression="SET #status = :status",
            ExpressionAttributeNames={"#status": "status"},
            ExpressionAttributeValues={":status": "refunded"},
            ConditionExpression="attribute_exists(chargeId)",
        )
    except CONDITIONAL_CHECK_FAILED:
        # Never collected: nothing to mark, and no record is created.
        pass

    return {"refundId": refund_id}


# --- loyalty / notification steps -------------------------------------------

def add_loyalty_points(customer_id, points):
    if not isinstance(points, (int, float)) or points <= 0:
        raise ValueError("Points must be a positive number")

    loyalty_entry = {
        "id": str(uuid.uuid4()),
        "customerId": customer_id,
        "points": int(points),
        "flag": "active",
        "date": now_iso(),
    }
    try:
        loyalty_table.put_item(Item=to_dynamodb(loyalty_entry))
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to add loyalty points: {str(exc)}")

    return {
        "message": "Loyalty points added successfully",
        "customerId": customer_id,
        "pointsAdded": int(points),
    }


def notify_booking(customer_id, price, booking_reference=None):
    booking_status = "confirmed" if booking_reference else "cancelled"
    reference_text = booking_reference or "most recent booking"

    return {
        "notificationId": secrets.token_urlsafe(16),
        "customerId": customer_id,
        "price": price,
        "status": booking_status,
        "subject": f"Booking {booking_status} for {reference_text}",
    }


# --- the Saga ---------------------------------------------------------------

def create_booking_flow(event):
    data = parse_body(event)

    if not data:
        return json_response(400, {"error": "Request body is required"})

    # Left outside the workflow try on purpose: for a JSON body that is not an
    # object this TypeError is what the monolith answered with (SI-19).
    data["customerId"] = claims_of(event).get("sub")

    booking_id = None
    payment_result = None
    flight_reserved = False

    try:
        # Step 1: reserve a seat (atomic).
        try:
            reserve_flight_seat(data["outboundFlightId"])
            flight_reserved = True
        except ValueError as exc:
            return json_response(400, {
                "error": f"Flight reservation failed: {str(exc)}",
                "step": "Reserve Flight",
            })

        # Step 2: write the UNCONFIRMED booking.
        try:
            booking_id = reserve_booking(data)
        except ValueError as exc:
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            return json_response(400, {
                "error": f"Booking reservation failed: {str(exc)}",
                "step": "Reserve Booking",
            })

        # Step 3: collect the payment.
        try:
            payment_result = collect_payment(data["chargeId"])
        except ValueError as exc:
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation rollback: {rollback_error}")
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            return json_response(400, {
                "error": f"Payment failed: {str(exc)}",
                "step": "Collect Payment",
                "bookingId": booking_id,
            })

        # Step 4: confirm the booking.
        try:
            booking_reference = confirm_booking(booking_id)
        except Exception as exc:  # noqa: BLE001
            print(f"CRITICAL: Booking confirmation failed after payment: {str(exc)}")
            try:
                refund_payment(data["chargeId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"CRITICAL: Payment refund failed during rollback: {rollback_error}")
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation rollback: {rollback_error}")
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            # The message stays as written even when the refund above failed
            # silently (business_rules[8]).
            return json_response(500, {
                "error": f"Booking confirmation failed: {str(exc)}",
                "step": "Confirm Booking",
                "bookingId": booking_id,
                "message": "Payment has been refunded",
            })

        # Step 5: loyalty points - must not fail the booking.
        try:
            add_loyalty_points(data["customerId"], int(payment_result["price"]))
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to add loyalty points: {str(exc)}")

        # Step 6: notification - must not fail the booking either.
        try:
            notification = notify_booking(
                data["customerId"],
                payment_result["price"],
                booking_reference,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to send notification: {str(exc)}")
            notification = {"status": "failed", "error": str(exc)}

        return json_response(201, {
            "bookingId": booking_id,
            "bookingReference": booking_reference,
            "status": "CONFIRMED",
            "payment": payment_result,
            "notification": notification,
        })

    except Exception as exc:  # noqa: BLE001 - the monolith's catch-all rollback
        print(f"UNEXPECTED ERROR in booking workflow: {str(exc)}")

        if payment_result:
            try:
                refund_payment(data["chargeId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during payment refund: {rollback_error}")

        if booking_id:
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation: {rollback_error}")

        if flight_reserved:
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release: {rollback_error}")

        return json_response(500, {
            "error": f"Unexpected error during booking: {str(exc)}",
            "message": "The booking has been rolled back. Please try again.",
        })


def lambda_handler(event, context):
    try:
        return create_booking_flow(event)
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})

