"""bookings-create: POST /bookings

The whole Saga runs inline in this one function - no queue, no invoke of
another function (D-6), so the booking is CONFIRMED when the 201 answers.

Order and failure semantics are the monolith's, step by step:
  Step 1  atomic seat decrement; failure -> 400 {'error': 'Flight reservation
          failed: ...', 'step': 'Reserve Flight'} with nothing to roll back.
  Step 2  PutItem the UNCONFIRMED booking; failure -> release the seat and
          400 {'step': 'Reserve Booking'} (no bookingId in that body).
  Step 3  collect the payment into PaymentTable; failure -> cancel the
          booking, release the seat, 400 {'step': 'Collect Payment',
          'bookingId'} with the bookingId of the booking that was created
          and then cancelled (SI-4).
  Step 4  conditional UpdateItem to CONFIRMED with a fresh bookingReference;
          failure -> refund, cancel, release and 500 {'step': 'Confirm
          Booking', 'bookingId', 'message': 'Payment has been refunded'} -
          that message is sent even when the refund itself failed silently
          (business_rules[8]).
  Step 5  loyalty points, 1:1 with the collected price (not the flight's
          ticketPrice); a failure is only logged and the 201 stands.
  Step 6  notification, a locally assembled dict; a failure is replaced by
          {'status': 'failed', 'error': ...} and the 201 stands.
Compensation steps never change the response (SI-18, GAP-17/D-16).

`customerId` is always overwritten by the verified identity, and that
assignment sits outside the business try on purpose: a JSON body that is
not an object then fails there with a TypeError that answers 500
{'error', 'type'} without touching a single table (SI-19). An unhashable
chargeId is rejected the same way the monolith rejected it - a TypeError
from the payment bookkeeping, not a ParamValidationError - so it escapes
Step 3's `except ValueError` and lands in the catch-all rollback (SI-19).
A missing `outboundFlightId` key keeps the monolith's inconsistent answer:
a KeyError that reaches the catch-all -> 500, no 400 validation message
(SI-3). No idempotency or de-duplication is added (SI-17).
Every response carries the app-wide headers (SI-14).
"""
import json
import os
import secrets
import uuid
from datetime import datetime, timezone
from decimal import Decimal

import boto3

FLIGHT_TABLE_NAME = os.environ["FLIGHT_TABLE_NAME"]
BOOKING_TABLE_NAME = os.environ["BOOKING_TABLE_NAME"]
PAYMENT_TABLE_NAME = os.environ["PAYMENT_TABLE_NAME"]
LOYALTY_TABLE_NAME = os.environ["LOYALTY_TABLE_NAME"]

_dynamodb = boto3.resource("dynamodb")
flight_table = _dynamodb.Table(FLIGHT_TABLE_NAME)
booking_table = _dynamodb.Table(BOOKING_TABLE_NAME)
payment_table = _dynamodb.Table(PAYMENT_TABLE_NAME)
loyalty_table = _dynamodb.Table(LOYALTY_TABLE_NAME)
CONDITIONAL_CHECK_FAILED = _dynamodb.meta.client.exceptions.ConditionalCheckFailedException


def json_response(status_code, payload):
    """Single place where the app-wide response headers are set (SI-14)."""
    return {
        "statusCode": status_code,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "*",
        },
        "body": json.dumps(payload),
    }


def to_dynamodb(value):
    """float -> Decimal(str(v)), as the monolith writes it (SI-16)."""
    if isinstance(value, float):
        return Decimal(str(value))
    if isinstance(value, dict):
        return {k: to_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [to_dynamodb(v) for v in value]
    return value


def from_dynamodb(value):
    """Decimal -> int when whole, float otherwise (SI-16)."""
    if isinstance(value, Decimal):
        if value % 1 == 0:
            return int(value)
        return float(value)
    if isinstance(value, dict):
        return {k: from_dynamodb(v) for k, v in value.items()}
    if isinstance(value, list):
        return [from_dynamodb(v) for v in value]
    return value


def now_iso():
    """Same shape as the monolith's datetime.now().isoformat(): no timezone
    suffix (SI-15)."""
    return datetime.now(timezone.utc).replace(tzinfo=None).isoformat()


def claims_of(event):
    """Identity comes from the gateway-verified claims only (SI-10)."""
    return (event.get("requestContext") or {}).get("authorizer", {}).get("claims") or {}


def parse_body(event):
    """A missing, empty or unparseable body reads as no data, the arm that
    answers 400 'Request body is required'."""
    raw = event.get("body")
    if raw is None or raw == "":
        return None
    if isinstance(raw, dict):
        return raw
    try:
        return json.loads(raw)
    except ValueError:
        return None


# --- catalog ------------------------------------------------------------------

def get_flight(flight_id):
    try:
        response = flight_table.get_item(Key={"id": flight_id})
    except Exception as exc:  # noqa: BLE001 - a failed read reads as missing
        print(f"Error getting flight {flight_id}: {str(exc)}")
        return None
    if "Item" in response:
        return from_dynamodb(response["Item"])
    return None


def reserve_flight_seat(flight_id):
    try:
        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity - :dec",
            ConditionExpression="seatCapacity > :zero AND attribute_exists(id)",
            ExpressionAttributeValues={":dec": 1, ":zero": 0},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError(f"Flight {flight_id} is fully booked or does not exist")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to reserve seat: {str(exc)}")


def release_flight_seat(flight_id):
    try:
        flight = get_flight(flight_id)
        if not flight:
            raise ValueError(f"Flight {flight_id} does not exist")

        flight_table.update_item(
            Key={"id": flight_id},
            UpdateExpression="SET seatCapacity = seatCapacity + :inc",
            ConditionExpression="seatCapacity < :max",
            ExpressionAttributeValues={":inc": 1, ":max": flight["maximumSeating"]},
            ReturnValues="UPDATED_NEW",
        )
        return True
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError("Cannot release seat, already at maximum capacity")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to release seat: {str(exc)}")


# --- bookings -----------------------------------------------------------------

def validate_booking_request(booking_data):
    required_fields = ["outboundFlightId", "customerId", "chargeId"]
    return all(field in booking_data for field in required_fields)


def create_booking(booking_data):
    booking = {
        "id": str(uuid.uuid4()),
        "bookingOutboundFlightId": booking_data["outboundFlightId"],
        "checkedIn": False,
        "customer": booking_data["customerId"],
        "paymentToken": booking_data["chargeId"],
        "status": "UNCONFIRMED",
        "createdAt": now_iso(),
        "bookingReference": None,
    }
    try:
        booking_table.put_item(Item=to_dynamodb(booking))
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to create booking: {str(exc)}")
    return booking


def reserve_booking(booking_data):
    if not validate_booking_request(booking_data):
        raise ValueError("Invalid booking request: missing required fields")
    return create_booking(booking_data)["id"]


def update_booking_status(booking_id, status, booking_reference=None):
    """One conditional write; the condition is the existence check, so no
    read-back of the item this request just wrote (D-16)."""
    update_expr = "SET #status = :status"
    expr_attr_names = {"#status": "status"}
    expr_attr_values = {":status": status}

    if booking_reference:
        update_expr += ", bookingReference = :ref"
        expr_attr_values[":ref"] = booking_reference

    try:
        booking_table.update_item(
            Key={"id": booking_id},
            UpdateExpression=update_expr,
            ExpressionAttributeNames=expr_attr_names,
            ExpressionAttributeValues=expr_attr_values,
            ConditionExpression="attribute_exists(id)",
            ReturnValues="ALL_NEW",
        )
    except CONDITIONAL_CHECK_FAILED:
        raise ValueError(f"Booking {booking_id} not found")
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to update booking: {str(exc)}")


def confirm_booking(booking_id):
    reference = secrets.token_urlsafe(4)
    update_booking_status(booking_id, "CONFIRMED", reference)
    return reference


def cancel_booking(booking_id):
    update_booking_status(booking_id, "CANCELLED")
    return True


# --- payments -----------------------------------------------------------------

def collect_payment(charge_id):
    """Simulation branch only (SI-7). The unhashable check comes first so a
    list/object chargeId raises the monolith's TypeError, before anything is
    written to PaymentTable (SI-19)."""
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    receipt_url = f"https://payment.example.com/receipts/{charge_id}"
    price = 150

    payment_table.put_item(Item=to_dynamodb({
        "chargeId": charge_id,
        "receiptUrl": receipt_url,
        "price": price,
        "status": "captured",
        "mode": "simulation",
    }))

    return {"receiptUrl": receipt_url, "price": price}


def refund_payment(charge_id):
    if not charge_id:
        raise ValueError("Invalid Charge ID")

    try:
        hash(charge_id)
    except TypeError:
        raise TypeError(f"unhashable type: '{type(charge_id).__name__}'")

    refund_id = secrets.token_urlsafe(16)

    try:
        payment_table.update_item(
            Key={"chargeId": charge_id},
            UpdateExpression="SET #status = :status",
            ExpressionAttributeNames={"#status": "status"},
            ExpressionAttributeValues={":status": "refunded"},
            ConditionExpression="attribute_exists(chargeId)",
        )
    except CONDITIONAL_CHECK_FAILED:
        # Never collected: nothing to mark and no record created.
        pass

    return {"refundId": refund_id}


# --- loyalty / notification ---------------------------------------------------

def add_loyalty_points(customer_id, points):
    if not isinstance(points, (int, float)) or points <= 0:
        raise ValueError("Points must be a positive number")

    loyalty_entry = {
        "id": str(uuid.uuid4()),
        "customerId": customer_id,
        "points": int(points),
        "flag": "active",
        "date": now_iso(),
    }
    try:
        loyalty_table.put_item(Item=to_dynamodb(loyalty_entry))
    except Exception as exc:  # noqa: BLE001
        raise ValueError(f"Failed to add loyalty points: {str(exc)}")

    return {
        "message": "Loyalty points added successfully",
        "customerId": customer_id,
        "pointsAdded": int(points),
    }


def process_booking_loyalty(customer_id, price):
    """1:1 price-to-points ratio on the collected price, not the flight's
    ticketPrice (business_rules[14])."""
    return add_loyalty_points(customer_id, int(price))


def notify_booking(customer_id, price, booking_reference=None):
    """Locally assembled notification, never stored or sent (SI-5)."""
    booking_status = "confirmed" if booking_reference else "cancelled"
    reference_text = booking_reference or "most recent booking"

    return {
        "notificationId": secrets.token_urlsafe(16),
        "customerId": customer_id,
        "price": price,
        "status": booking_status,
        "subject": f"Booking {booking_status} for {reference_text}",
    }


# --- the Saga -----------------------------------------------------------------

def create_booking_flow(event):
    data = parse_body(event)

    if not data:
        return json_response(400, {"error": "Request body is required"})

    # customerId is taken from the verified identity, whatever the body said
    # (business_rules[1]). Kept outside the workflow try so a non-object body
    # raises here exactly as it did in the monolith (SI-19).
    data["customerId"] = claims_of(event).get("sub")

    booking_id = None
    payment_result = None
    flight_reserved = False

    try:
        # Step 1: reserve the seat (atomic).
        try:
            reserve_flight_seat(data["outboundFlightId"])
            flight_reserved = True
        except ValueError as exc:
            return json_response(400, {
                "error": f"Flight reservation failed: {str(exc)}",
                "step": "Reserve Flight",
            })

        # Step 2: write the UNCONFIRMED booking.
        try:
            booking_id = reserve_booking(data)
        except ValueError as exc:
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            return json_response(400, {
                "error": f"Booking reservation failed: {str(exc)}",
                "step": "Reserve Booking",
            })

        # Step 3: collect the payment.
        try:
            payment_result = collect_payment(data["chargeId"])
        except ValueError as exc:
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation rollback: {rollback_error}")
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            return json_response(400, {
                "error": f"Payment failed: {str(exc)}",
                "step": "Collect Payment",
                "bookingId": booking_id,
            })

        # Step 4: confirm the booking.
        try:
            booking_reference = confirm_booking(booking_id)
        except Exception as exc:  # noqa: BLE001
            print(f"CRITICAL: Booking confirmation failed after payment: {str(exc)}")
            try:
                refund_payment(data["chargeId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"CRITICAL: Payment refund failed during rollback: {rollback_error}")
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation rollback: {rollback_error}")
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release rollback: {rollback_error}")
            # The message is the response the monolith sends even when the
            # refund above was swallowed (business_rules[8]).
            return json_response(500, {
                "error": f"Booking confirmation failed: {str(exc)}",
                "step": "Confirm Booking",
                "bookingId": booking_id,
                "message": "Payment has been refunded",
            })

        # Step 5: loyalty points - must not fail the booking.
        try:
            process_booking_loyalty(data["customerId"], payment_result["price"])
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to add loyalty points: {str(exc)}")

        # Step 6: notification - must not fail the booking either.
        try:
            notification = notify_booking(
                data["customerId"],
                payment_result["price"],
                booking_reference,
            )
        except Exception as exc:  # noqa: BLE001
            print(f"Warning: Failed to send notification: {str(exc)}")
            notification = {"status": "failed", "error": str(exc)}

        return json_response(201, {
            "bookingId": booking_id,
            "bookingReference": booking_reference,
            "status": "CONFIRMED",
            "payment": payment_result,
            "notification": notification,
        })

    except Exception as exc:  # noqa: BLE001 - the catch-all rollback
        print(f"UNEXPECTED ERROR in booking workflow: {str(exc)}")

        if payment_result:
            try:
                refund_payment(data["chargeId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during payment refund: {rollback_error}")

        if booking_id:
            try:
                cancel_booking(booking_id)
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during booking cancellation: {rollback_error}")

        if flight_reserved:
            try:
                release_flight_seat(data["outboundFlightId"])
            except Exception as rollback_error:  # noqa: BLE001
                print(f"Error during flight seat release: {rollback_error}")

        return json_response(500, {
            "error": f"Unexpected error during booking: {str(exc)}",
            "message": "The booking has been rolled back. Please try again.",
        })


def lambda_handler(event, context):
    try:
        return create_booking_flow(event)
    except ValueError as exc:
        return json_response(400, {"error": str(exc), "type": "ValueError"})
    except Exception as exc:  # noqa: BLE001 - same mapping as the monolith
        return json_response(500, {"error": str(exc), "type": type(exc).__name__})

